from collections import Counter
class Solution:
 def sumOfUnique(self,nums):return sum(x for x,n in Counter(nums).items() if n==1)

class Solution:
 def check(self,nums):
  drops=sum(nums[i]>nums[(i+1)%len(nums)] for i in range(len(nums)))
  return drops<=1

class Solution:
 def mergeAlternately(self,word1,word2):
  out=[]
  for i in range(max(len(word1),len(word2))):
   if i<len(word1):out.append(word1[i])
   if i<len(word2):out.append(word2[i])
  return ''.join(out)

class Solution:
 def countMatches(self,items,ruleKey,ruleValue):
  idx={'type':0,'color':1,'name':2}[ruleKey]
  return sum(item[idx]==ruleValue for item in items)

class Solution:
 def nearestValidPoint(self,x,y,points):
  best=-1;dist=10**9
  for i,(a,b) in enumerate(points):
   if a==x or b==y:
    d=abs(a-x)+abs(b-y)
    if d<dist:best=i;dist=d
  return best

class Solution:
 def arraySign(self,nums):
  neg=sum(x<0 for x in nums)
  return 0 if any(x==0 for x in nums) else (-1 if neg%2 else 1)

class Solution:
 def sumBase(self,n,k):
  total=0
  while n:total+=n%k;n//=k
  return total

class Solution:
 def replaceDigits(self,s):
  a=list(s)
  for i in range(1,len(a),2):a[i]=chr(ord(a[i-1])+int(a[i]))
  return ''.join(a)
